// FUNCTION: BFME2 0x003742E3 size=166 name=?calcStealthedStatusForPlayer@StealthUpdate@@QAE?AW4StealthLookType@@PBVObject@@PBVPlayer@@@Z evidence=N:ledger tier=A
StealthLookType StealthUpdate::calcStealthedStatusForPlayer(const Object *obj, const Player *player)
{
	if (!(obj->m_privateStatus & 1))
	{
		Relationship relationship = (Relationship)1;
		if (const_cast<Object *>(obj)->testStatus((ObjectStatusTypes)0xF))
		{
			if (obj->m_team)
				relationship = obj->m_team->getRelationship(player->m_defaultTeam);
			if (!const_cast<Player *>(player)->isPlayerActive())
				relationship = (Relationship)2;
			const StealthUpdateModuleData *data = (const StealthUpdateModuleData *)getModuleData();
			if (data->m_disguisesAsTeam)
			{
				if (relationship != 2 && m_disguiseTemplate != 0)
					return STEALTH_LOOK_DISGUISED_ENEMY;
			}
			else if (const_cast<Object *>(obj)->testStatus((ObjectStatusTypes)0x11))
			{
				if (data->m_detectedByFriendliesOnly)
					return STEALTH_LOOK_NONE;
				return (relationship == 2) ? STEALTH_LOOK_VISIBLE_FRIENDLY_DETECTED : STEALTH_LOOK_VISIBLE_DETECTED;
			}
			else
				return (StealthLookType)((relationship != 2) * 4 + STEALTH_LOOK_VISIBLE_FRIENDLY);
		}
	}
	return STEALTH_LOOK_NONE;
}

