// FUNCTION: BFME2 0x0037446E size=935 name=?markAsDetected@StealthUpdate@@QAEXIHPAVObject@@_N@Z evidence=N:ledger tier=A
void StealthUpdate::markAsDetected(UnsignedInt numFrames, Int feedback, Object *detector, Bool throughContainer)
{
	Object *self = getObject();
	const StealthUpdateModuleData *data = (const StealthUpdateModuleData *)m_moduleData;
	Drawable *draw = self->getDrawable();

	if (!self->testStatus(OBJECT_STATUS_DETECTED)) {
		if (throughContainer) {
			Object *rider = self->rva002931F5(false);
			if (rider && ((getStealthLevel() & 0x400) || rider == self)) {
				HordeContainInterface *contain = rider->rva0028C197();
				if (contain == 0)
					return;
				StealthUpdate *riderStealth = (StealthUpdate *)rider->rva0028F4BC();
				if (riderStealth)
					riderStealth->markAsDetected(numFrames, feedback, detector, false);
				ContainmentListView items;
				contain->hordeSlot66(&items);
				for (_STL::list<Object *>::const_iterator it = items.objects().begin(); it != items.objects().end(); ++it) {
					StealthUpdate *stealth = (StealthUpdate *)(*it)->rva0028F4BC();
					if (stealth)
						stealth->markAsDetected(numFrames, feedback, detector, false);
				}
				return;
			}
		}

		setStatusOnSelfAndContained(OBJECT_STATUS_DETECTED, true);

		Player *thisPlayer = self->getControllingPlayer();

		if (m_disguiseTemplate)
			disguiseAsObject(0);

		if (data->m_orderIdleEnemiesToAttackMeUponReveal) {
			Int numPlayers = ThePlayerList->getPlayerCount();
			for (Int n = 0; n < numPlayers; ++n) {
				Player *player = ThePlayerList->getNthPlayer(n);
				if (player && player->getRelationship(thisPlayer->m_defaultTeam) == 0)
					player->iterateObjects(setWakeupIfInRange, self);
			}
		}

		if (draw && feedback) {
			if (ThePlayerList->getLocalPlayer() == self->getControllingPlayer()) {
				if (feedback == 2) {
					TheRadar->createEvent(self->getPosition(), (RadarEventType)9, 4.0f);
					AudioEventRTS sound(TheAudio->getMiscAudio()->m_stealthNeutralizedSound, self->getID());
					sound.setPlayerIndex(ThePlayerList->getLocalPlayer()->getPlayerIndex());
					TheAudio->addAudioEvent(&sound);
					TheInGameUI->multiplayerMessage(TheGameText->fetch("MESSAGE:StealthNeutralized", 0));
					TheEva->reportEvaEvent((EvaEventID)data->m_evaEventDetectedOwner, self->getPosition(), 0);
				}
			} else if (ThePlayerList->getLocalPlayer()->getRelationship(self) != 2) {
				if (!draw->m_unk0x43D[3]) {
					TheRadar->createEvent(self->getPosition(), (RadarEventType)8, 4.0f);
					if (detector) {
						AudioEventRTS sound(TheAudio->getMiscAudio()->m_stealthDiscoveredSound, detector->getID());
						sound.setPlayerIndex(ThePlayerList->getLocalPlayer()->getPlayerIndex());
						TheAudio->addAudioEvent(&sound);
						TheInGameUI->multiplayerMessage(TheGameText->fetch("MESSAGE:StealthDiscovered", 0));
						TheEva->reportEvaEvent((EvaEventID)data->m_evaEventDetectedEnemy, detector->getPosition(), self->getPosition());
					}
				}
			} else if (feedback == 2) {
				AudioEventRTS sound(TheAudio->getMiscAudio()->m_stealthDiscoveredSound, self->getID());
				sound.setPlayerIndex(ThePlayerList->getLocalPlayer()->getPlayerIndex());
				TheAudio->addAudioEvent(&sound);
				TheEva->reportEvaEvent((EvaEventID)data->m_evaEventDetectedAlly, self->getPosition(), 0);
			}
		}
	}

	rva00373EEC(numFrames);
}

